import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.Bg-Zxr5O.js";const T=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Macro-Settings.md","filePath":"manual-en/Macro-Settings.md","lastUpdated":1785684581000}'),s={name:"manual-en/Macro-Settings.md"};function i(r,e,c,d,l,h){return t(),o("div",null,[...e[0]||(e[0]=[n('<h4 id="_14-2-11-macro-settings" tabindex="-1">14.2.11 Macro Settings <a class="header-anchor" href="#_14-2-11-macro-settings" aria-label="Permalink to &quot;14.2.11 Macro Settings&quot;">​</a></h4><p>Some macro behavior is controlled through the SET command (see <a href="./SET">SET</a>). This section describes these settings.</p><p>Any SET command that changes these settings within a macro body only takes effect following the macro. This is because PSPP expands a macro’s entire body at once, so that the SET command inside the body only executes afterwards.</p><p>The MEXPAND setting (see <a href="./SET#SET-MEXPAND">SET MEXPAND</a>) controls whether macros will be expanded at all. By default, macro expansion is on. To avoid expansion of macros called within a macro body, use <code>!OFFEXPAND</code> and <code>!ONEXPAND</code> (see <a href="./Controlling-Macro-Expansion">Controlling Macro Expansion</a>).</p><p>When MPRINT (see <a href="./SET#SET-MPRINT">SET MPRINT</a>) is turned on, PSPP outputs an expansion of each macro called. This feature can be useful for debugging macro definitions. For reading the expanded version, note that macro expansion removes comments and standardizes white space.</p><p>MNEST (see <a href="./SET#SET-MNEST">SET MNEST</a>) limits the depth of expansion of macro calls, that is, the nesting level of macro expansion. The default is 50. This is mainly useful to avoid infinite expansion in the case of a macro that calls itself.</p><p>MITERATE (see <a href="./SET#SET-MITERATE">SET MITERATE</a>) limits the number of iterations in a <code>!DO</code> construct. The default is 1000.</p>',7)])])}const p=a(s,[["render",i]]);export{T as __pageData,p as default};
